AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE void GET_T_GIVEN_EY(const amrex::Real e, const amrex::Real y[], amrex::Real& t, int& ierr)
{
#ifdef CONVERGENCE
const int maxiter = 5000;
const amrex::Real tol = 1.e-12;
#else
const int maxiter = 200;
const amrex::Real tol = 1.e-6;
#endif
amrex::Real tmin = 300.0;// max lower bound for thermo def
amrex::Real tmax = 5000.0;// min upper bound for thermo def
amrex::Real e1,emin,emax,cv,t1,dt;
CKUBMS(tmin, y, emin);
CKUBMS(tmax, y, emax);
if (e < emin) {
// Linear Extrapolation below tmin
CKCVBS(tmin, y, cv);
t = tmin - (emin-e)/cv;
ierr = 1;
return;
}
if (e > emax) {
// Linear Extrapolation above tmax
CKCVBS(tmax, y, cv);
t = tmax - (emax-e)/cv;
ierr = 1;
return;
}
t1 = t;
if (t1 < tmin || t1 > tmax) {
t1 = tmin + (tmax-tmin)/(emax-emin)*(e-emin);
}
for (int i = 0; i < maxiter; ++i) {
CKUBMS(t1,y,e1);
CKCVBS(t1,y,cv);
dt = (e - e1) / cv;
if (dt > 100.) { dt = 100.; }
else if (dt < -100.) { dt = -100.; }
else if (fabs(dt) < tol) {break;}
t1 += dt;
}
t = t1;
ierr = 0;
}
